	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Achrei Mot", "פרשת אחרי מות פותחת בפירוט סדר עבודת יום הכיפורים במשכן: נוסף על קורבנות מיוחדים ועל עבודת הקטורת, עבודת הכהן הגדול כוללת הטלת גורלות לשני שעירי החטאת: אחד מהם מוקרב על גבי המזבח, והאחר - השעיר לעזאזל - נושא את עוונות בני ישראל ונשלח למדבר. הפרשה ממשיכה באיסור לשחוט מחוץ למשכן, באיסור להקריב קורבנות מחוץ למשכן, באיסור אכילת דם, בחובת כיסוי הדם בעוף ובחיה ובטומאת נבלה וטרפה. הפרשה מסתיימת ברשימת איסורי עריות.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Asara B'Tevet", "צום המציין את המצור על ירושלים")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Balak", "בפרשת בלק מסופר על בלק מלך מואב הפונה לבלעם ומבקש ממנו לקלל את בני ישראל. אלוהים מרשה לבלעם ללכת לקללם בתנאי שישמע בקול אלוהים. בדרך האתון של בלעם פותחת את פיה ומדברת. בלעם מנסה לקלל את בני ישראל שלוש פעמים, ובכל פעם קללתו הופכת לברכה בפיו. כאשר ישראל מתחילים לזנות עם בנות מואב ולזבוח לאלוהיהן אלוהים שולח מגפה בעם, ונהרגים בה עשרות אלפים. המגפה מסתיימת אחרי מעשה הקנאות של פינחס.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Bamidbar", "בפרשת במדבר מתואר מפקד בני ישראל וסידור המחנה לפי שבטים מסביב למשכן. שבט לוי ממונה על נשיאת המשכן וכליו במהלך המסע במדבר, ולכל משפחה משלוש המשפחות בשבט - גרשון, קהת, ומררי - יש תפקיד מסוים.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Bechukotai", "בפרשת בחקתי, הפרשה האחרונה בספר ויקרא, מתואר השכר המובטח לבני ישראל אם ישמרו את דיני התורה: שגשוג כלכלי וחקלאי, שלום והצלחה צבאית והשראת שכינה. הפרשה מאריכה בתיאור העונשים והקללות שיבואו על בני ישראל אם לא ישמרו את דיני התורה: שפל כלכלי, רעב, מחלות, תבוסה במלחמות וגלות. אלוהים מבטיח שיזכור את בריתו עם האבות והארץ, והפרשה מסתיימת בדיני ערכין באדם ובקרקעות.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Beha'alotcha", "בפרשת בהעלותך אהרן מצטווה להדליק את הנרות במנורה, ושבט לוי מוקדש לעבודת המשכן. בעקבות פנייה של קבוצה של טמאים לנפש אדם שאינם יכולים להקריב את קורבן הפסח בזמנו, מתחדש דין פסח שני, שמעניק לאדם טמא או נמצא בדרך רחוקה הזדמנות שנייה להביא את הקורבן. משה מצטווה לעשות חצוצרות למסע העדה, לכינוס העם ולתקיעה במועדים ובשעת מלחמה. במסגרת פירוט מסעות בני ישראל במדבר מסופר על תלונות העם ותאוותיו ועל צרעת מרים.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Behar", "בפרשת בהר מובאים דיני שבת הארץ (שמיטה), החלה בכל שבע שנים ואסורה בה עבודת האדמה. בשנת החמישים, היא שנת היובל, נוסף על שביתה מעבודת האדמה יש לשחרר את העבדים, והקרקעות חוזרות לבעליהן המקוריים. מפורטים גם דיני מכירת קרקעות, דיני מכירת עבדים, דיני אונאת ממון ואונאת דברים, איסור ריבית ואיסורים הקשורים לעבודה זרה.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Ben-Gurion Day", "יום המציין את חייו וחזונו של ראש הממשלה הראשון של ישראל, דוד בן-גוריון")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Bereshit", "פרשת בראשית, הפרשה הראשונה בתורה, מתארת את ראשיתו של העולם. אלוהים בורא את העולם בשישה ימים ונח ביום השביעי. הוא מניח את האדם בגן עדן ומצווה עליו ליהנות מפירות הגן מלבד מפרי עץ הדעת. בעצת הנחש חוה ואדם אוכלים מעץ הדעת, ולכן מגורשים מגן עדן. בנם הבכור קין הורג את אחיו הצעיר הבל, וקין נידון להיות נע ונד בארץ.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Beshalach", "בפרשת בשלח מתוארות קריעת ים סוף, טביעת חיל מצרים, הצלת בני ישראל ושירת הים ששרו משה ובני ישראל על ים סוף, וכן שירת מרים. בני ישראל מגיעים למדבר ומתלוננים, ואלוהים ממתיק להם מים מרים ומספק להם מן ושליו לאכול. משה מכה בצור ברפידים ומוציא ממנו מים, ויהושע מנהיג שם את העם במלחמה נגד עמלק.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Birkat Hachamah", "ברכה יהודית נדירה הנאמרת אחת ל-28 שנים כהודיה לאל על בריאת החמה")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Bo", "בפרשת בא מסופר על שלוש המכות האחרונות שהאל מביא על מצרים. אחרי מכת הארבה נופל חושך כבד על מצרים במשך שלושה ימים. אלוהים מצווה את בני ישראל להקריב את קורבן הפסח, למרוח דם על מזוזות הבית, ולא לצאת מפתח הבית כדי להינצל ממוות. באותו לילה המשחית הורג את כל בכורות מצרים במכה האחרונה, מכת בכורות. פרעה והמצרים מגרשים את בני ישראל ממצרים.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Chag HaBanot", "חג הבנות של חנוכה (עיד אל-בנאת), שמקורו ביהדות צפון אפריקה ונשתמר בעיקר בתוניסיה")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Chanukah", "חנוכה, חג החנוכה מחדש היהודי. ידוע גם כחג האורים; החג נחגג במשך שמונה ימים על ידי הדלקת נרות בחנוכייה")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Chayei Sara", "פרשת חיי שרה נפתחת במות שרה. אברהם קונה את מערת המכפלה וקובר בה את אשתו. אברהם שולח את עבדו למולדתו חרן למצוא אישה לבנו יצחק. העבד פוגש את רבקה על יד הבאר, והיא מציעה לדלות מים לו ולגמליו. לאחר משא ומתן עם משפחת רבקה העבד מביא את רבקה לארץ כנען, ויצחק לוקח אותה לאישה. אברהם לוקח אישה נוספת, מוליד ילדים ומת בן 175.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Chukat", "בפרשת חקת מפורט תהליך טהרת האדם מטומאת מת באפר פרה אדומה. מרים מתה, והעם מתלונן שהוא צמא למים. אלוהים מצווה את משה לדבר אל הסלע, ומשה מכה בסלע להוציא ממנו מים. משה ואהרן נענשים שלא יזכו להיכנס לארץ, ואהרן מת בהר ההר. העם מתלונן על האוכל במדבר ונענש במתקפת נחשים. העם מנצח במלחמה נגד סיחון ועוג שני מלכי האמורי בעבר הירדן המזרחי.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Days of the Omer", "7 שבועות מהלילה השני של פסח ועד ליום לפני שבועות. נקרא גם ספירת העומר; מנהג הכולל ספירה מילולית של כל אחד מארבעים ותשעה הימים בין שני החגים")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Devarim", "דברים היא הפרשה הראשונה בספר דברים, החומש החמישי והאחרון בתורה. בספר מובאים נאומי משה, שבהם הוא מזכיר אירועים מהעבר, סוקר מצוות שכבר ניתנו ומצווה מצוות חדשות. בפרשה משה מספר על הצורך במינוי שופטים להנהגת העם. הוא גם מזכיר את חטא המרגלים, שבו התלונן העם על הכניסה העתידית לארץ כנען, את העונש שהוטל על העם לנדוד במדבר ארבעים שנה ואת מלחמות ישראל במדבר.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Eikev", "בפרשת עקב משה מבטיח ששמירת המצוות תגרור אחריה שגשוג והצלחה צבאית. משה מזכיר לעם את המן שאכלו במדבר ואת החטאים והתלונות וכן מתאר במפורט את חטא העגל. משה מדגיש את הייחודיות של הארץ המובטחת ושונה את פרשת 'והיה אם שמוע', המתארת את שכר קיום המצוות ועונש הגלות על עבודה זרה.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Emor", "פרשת אמור מפרטת חוקים הנוגעים לעבודת הכהנים במשכן, להתנהלותם מחוץ למשכן ולאכילת קודשים. במרכז הפרשה ניצבים דיני המועדים: שבת, חג המצות, ספירת העומר, חג השבועות, ראש השנה (יום זיכרון תרועה), יום הכיפורים וחג הסוכות. בסוף הפרשה מסופר סיפור על אדם המקלל את אלוהים.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Erev Yom Kippur", "ערב יום הכיפורים, הכולל את תפילת כל נדרי. צום יום הכיפורים מתחיל עם שקיעת החמה ונמשך 25 שעות")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Family Day", "יום המשפחה, יום להוקרת התא המשפחתי")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Ha'azinu", "בפרשת האזינו מובאת שירה שמשבחת את אלוהים ומבקרת את העבירות העתידיות של בני ישראל. בשירה מתוארים הסבל והצרות שיבואו על העם וכן העונשים העתידים לבוא על אויבי עם ישראל. הפרשה מסתיימת בציווי על משה לעלות להר נבו, שבו ימות.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Hebrew Language Day", "יום לקידום השפה העברית בישראל וברחבי העולם. חל ביום הולדתו של אליעזר בן יהודה, מחייה השפה העברית")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Herzl Day", "יום המציין את חייו וחזונו של המנהיג הציוני בנימין זאב הרצל")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Jabotinsky Day", "יום המציין את חייו וחזונו של המנהיג הציוני זאב ז'בוטינסקי")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Kedoshim", "פרשת קדושים פותחת בציווי לבני ישראל שיהיו קדושים ומפרטת עשרות דינים בתחומי פולחן וחברה, כגון שבת וקורבנות, איסור כלאיים, מצוות ואהבת לרעך כמוך, החובה להלוות לעניים ואיסור נקמה. בסוף הפרשה מפורטים עונשים בתחום איסורי עריות ועבודה זרה.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Ki Tavo", "בפרשת כי תבוא מובאות מצוות מקרא ביכורים, טקסט הודיה שנאמר בשעת הבאת הביכורים, ומצוות וידוי מעשרות, נוסח שנאמר לאחר השלמת חובת הבאת המעשרות. משה מצווה על מעמד הברכה והקללה על הר גריזים והר עיבל אחרי הכניסה לארץ ומתאר את הברכות הרבות שיחולו על בני ישראל אם ישמרו את מצוות התורה ואת הקללות והעונשים שיבואו על העם אם לא ישמרו את המצוות.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Ki Teitzei", "בפרשת כי תצא מספר הדינים הגדול ביותר בהשוואה לכל פרשה אחרת בתורה. במצוות מפורטים דיני ירושה ודיני קבורת המת, מצוות השבת אבדה ודינים אחרים להתנהלות חברתית מוסרית, כמו מתנות עניים, איסור ריבית ואיסור הלנת שכר. מתוארים גם דיני משפחה כמו דיני נישואין, גירושין, אישות, ייבום וחליצה.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Ki Tisa", "בפרשת כי תשא אלוהים מצווה את משה לפקוד את העם על ידי תרומה של מחצית השקל לכל אדם. משה מצטווה לעשות את הכיור ואת כנו, את שמן המשחה ואת סממני קטורת הסמים. בני ישראל מקריבים קורבנות לעגל זהב; אלוהים מאיים להשמיד את העם, ומשה מתפלל להצלתם. משה יורד מההר ושובר את לוחות הברית ומעניש עם בני לוי את עובדי העגל. משה עולה להר ומקבל את הלוחות השניים. אלוהים כורת ברית חדשה עם בני ישראל.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Korach", "בפרשת קרח מתואר כיצד קרח, דתן ואבירם ו-250 מנהיגים נוספים מערערים על מנהיגות משה ועל כהונת אהרן ומובילים נגדם מרד. אלוהים מעניש את המורדים: חלקם נשרפים באש וחלקם נבלעים באדמה בדרך נס. העימות מסתיים בפריחת מטה אהרן, המוכיחה את בחירתו על ידי האל, ובסוף הפרשה מובא ציווי על מתנות כהונה ולווייה.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Lag BaOmer", "היום ה-33 לספירת העומר. החג מהווה הפוגה זמנית ממנהגי האבלות של תקופת ספירת העומר. המנהגים כוללים הדלקת מדורות, תספורות וחתונות")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Lech-Lecha", "בפרשת לך-לך מתוארת ההתגלות הראשונה של אלוהים לאברם. אברם יוצא עם אשתו שרי ובן אחיו לוט למסע במצוות אלוהים ומגיע לארץ כנען. שרי העקרה נותנת לאברם את שפחתה הגר. הגר יולדת את ישמעאל. אלוהים מצווה את אברם למול את עצמו ואת בני ביתו וכורת ברית עם אברם ועם זרעו. במסגרת הברית אלוהים משנה את שמו של אברם לאברהם ואת שמה של שרי לשרה.")
