	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Matot", "פרשת מטות פותחת בדיני נדרים ושבועות. משה מצווה את בני ישראל להילחם במדיין, ולאחר הניצחון העם מחלק את השלל. בני גד ובני ראובן מבקשים לנחול מחוץ לארץ כנען, בעבר הירדן המזרחי, משום שיש להם מקנה רב. משה מתנגד בתחילה, אך לבסוף מגיע להסדר שלפיו ינחלו השבטים בעבר הירדן המזרחי בתנאי שיעברו חלוצים במלחמה על כיבוש הארץ.")
