	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Miketz", "בפרשת מקץ יוסף פותר את חלומותיו של פרעה ועולה לגדולה בתפקיד המשנה למלך. אחי יוסף מגיעים למצרים לקנות אוכל בשל הרעב הכבד השורר בארץ כנען, ויוסף מאשים אותם בריגול. הוא דורש שישובו למצרים עם אחיהם הצעיר בנימין. יוסף נותן להם אוכל ושולח אותם בשלום, אך מסתיר גביע כסף באמתחת בנימין ומאשים אותו בגנבה.")
