	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Noach", "פרשת נח עוסקת בהחלטה של האל להשמיד את האנושות במבול. אלוהים מצווה את נח לבנות תיבה כדי להציל את נח, את בני משפחתו ובעלי חיים. עם שוך המבול נח ומשפחתו יוצאים מן התיבה, וילדיו של נח מולידים דורות של צאצאים. אלוהים בולל את שפת האדם לאחר הניסיון לבנות את מגדל בבל. תרח עוזב את ביתו ויוצא למסע עם משפחתו, ובהם בנו אברם וכלתו שרי.")
