	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Vayechi", "פרשת ויחי היא הפרשה האחרונה בספר בראשית. יעקב מתכונן למותו ומשביע את יוסף שיקבור אותו עם אבותיו במערת המכפלה. יעקב מברך את שני בני יוסף ואת 12 בניו, ומת. בני יעקב קוברים אותו בארץ כנען. אחי יוסף חוששים שאחרי מות יעקב יתנקם בהם יוסף על כל מה שעשו לו. יוסף סולח לאחיו ומשביע אותם שיקברו אותו בארץ כנען. הפרשה מסתיימת בתיאור מותו של יוסף.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Vayeilech", "בפרשת וילך משה מסכם את תקופת הנהגתו ומעביר את ההנהגה ליהושע. מתוארת מצוות הקהל, שהתורה נקראת בה במעמד מיוחד של כל העם שמתקיים בחג הסוכות שבמוצאי שנת השמיטה \"במקום אשר יבחר ה'.\" משה מתאר כיצד בני ישראל ייחטאו בעבודה זרה וייענשו. אלוהים מצווה את משה לכתוב שירה, עדות לבני ישראל.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Vayera", "בפרשת וירא מגיעים אורחים לאוהלו של אברהם להודיע לו ששרה עתידה ללדת בן. על אף מאמציו של אברהם לשכנע את אלוהים שלא להחריב את ערי החטאים סדום ועמורה, אלוהים מחריב את הערים ועוד שתי ערים הסמוכות להן. לוט ומשפחתו ניצלים מתוך ההפכה. שרה יולדת את יצחק, ואברהם משלח מביתו את הגר וישמעאל. אלוהים מצווה את אברהם להקריב את יצחק בנו, אך מלאך אלוהים עוצר את אברהם בשעת מעשה.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Vayeshev", "פרשת וישב מספרת את סיפור יוסף ואחיו ומתארת את המתיחות ביניהם, שמובילה למכירתו ולעבדותו במצרים. אשת פוטיפר מנסה לפתות את יוסף, ומאחר שהוא אינו נענה לה היא טופלת עליו עלילת שווא, ויוסף נשלח לבית הסוהר. הפרשה מספרת גם על מעשה תמר ויהודה: תמר נישאת לשני בניו של יהודה, ושניהם מתים. תמר נותרת אלמנה ודורשת מיהודה שבנו הקטן ייבם אותה.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Vayetzei", "בפרשת ויצא מתואר חלום יעקב, ובו מלאכים עולים בסולם ויורדים בו. יעקב ממשיך בדרכו לבית לבן אחי אימו, ושם הוא מכיר את בת דודו רחל ומבקש להתחתן איתה. לבן מסכים בתנאי שיעקב יעבוד אצלו. אחרי שבע שנים לבן מרמה את יעקב ונותן לו את בתו הבכירה לאה במקום את רחל, אך לאחר משא ומתן מסכים לתת לו לאישה גם את רחל. לאה ורחל ושפחותיהן בלהה וזלפה יולדות ליעקב ילדים.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Vayigash", "בפרשת ויגש יהודה מתחנן לפני יוסף שישחרר את בנימין ממאסר. יוסף מגלה לאחיו את זהותו, והם בוכים ומתפייסים. אחי יוסף מביאים את יעקב אביהם מכנען למצרים, ויעקב ובניו מתיישבים בגושן. יוסף קונה את רוב אדמות מצרים תמורת מזון שאגר בשנות השובע.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Vayikra", "בפרשת ויקרא אלוהים קורא למשה ומצווה אותו על עבודת הקורבנות. הפרשה פותחת בתיאור קורבנות העולה, המנחה (שאיננה קורבן מן הבהמה אלא מן הצומח) והשלמים, בפירוט כמה אפשרויות להקרבת כל סוג קורבן. לאחר מכן מתוארים קורבנות חטאת ואשם ומפורטים המצבים שבהם מובא כל אחד מן הקורבנות.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Vayishlach", "פרשת וישלח ממשיכה לעקוב אחרי יעקב ומשפחתו. יעקב נאבק עם איש (שלפי הפרשנות המקובלת הוא מלאך אלוהים), ובסיום המאבק האיש מעניק לו את השם ישראל. יעקב מתפייס עם אחיו עשו. דינה, בתו של יעקב, נאנסת ונשבית בידי נסיך חיווי, ואחיה הורגים את כל הזכרים בעיר ומשיבים אליהם את דינה. רחל מתה בשעת לידתו של בנימין, הצעיר בבני יעקב.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Vezot Haberakhah", "בפרשת וזאת הברכה, הפרשה האחרונה בחמשת חומשי התורה, משה מברך את כל שבטי ישראל חוץ משבט שמעון. משה עולה להר נבו, רואה את הארץ המובטחת ומת בן מאה ועשרים שנה. בני ישראל בוכים על מיתת משה שלושים יום, ויהושע מנהיג את העם מכאן והלאה. משה מתואר כנביא שלא קם עוד כמוהו בישראל.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Yitro", "יתרו חותן משה מופיע במחנה ישראל עם ציפורה בתו ושני בניה לאחר ששמע על הניסים שחולל אלוהים לישראל ביציאת מצרים. יתרו נחשף להנהגתו של משה ומציע לו להקים מערכת משפט יעילה יותר. משה מכין את העם לקבלת התורה בהר סיני ומרחיק את בני ישראל מההר. אלוהים מתגלה לעיני העם בעשן ואש על ראש ההר במעמד עוצמתי המלווה בקולות וברקים וקול שופר ונותן לעם את עשרת הדיברות.")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Yitzhak Rabin Memorial Day", "יום הזיכרון ליצחק רבין. מציין את חייו של ראש ממשלת ישראל יצחק רבין")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Yom HaAliyah", "מציין את העלייה למדינת ישראל")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Yom HaAliyah School Observance", "יום העלייה כפי שמצוין בבתי הספר בישראל")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Yom HaAtzma'ut", "יום העצמאות. מציין את הכרזת העצמאות של ישראל בשנת 1948. למרות שיום העצמאות מצוין בדרך כלל בה' באייר, הוא עשוי להיות מוקדם או להידחות אם קיום החג (או יום הזיכרון שתמיד קודם לו) יתנגש עם השבת")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Yom HaShoah", "יום הזיכרון לשואה ולגבורה")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Yom HaZikaron", "יום הזיכרון לחללי מערכות ישראל. זוכר את אלו שנפלו במלחמת העצמאות ובמלחמות ישראל האחרות. השם המלא של החג הוא “יום הזיכרון לחללי מערכות ישראל ולנפגעי פעולות האיבה״. למרות שיום הזיכרון מצוין בדרך כלל בד' באייר, הוא עשוי להיות מוקדם או להידחות אם קיום היום (או יום העצמאות שבא תמיד אחריו) יתנגש עם השבת")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Yom Kippur", "יום הכיפורים. היום הקדוש ביותר בשנה ביהדות, המצוין באופן מסורתי בצום של 25 שעות ותפילה אינטנסיבית")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Yom Kippur Katan", "יום כיפור קטן. יום כפרה החל מדי חודש ביום שלפני כל ראש חודש")
	Catalog.SetString(tag_he_x_NoNikud, "MEMO:Yom Yerushalayim", "יום ירושלים. מציין את איחודה מחדש של ירושלים בשנת 1967")
